272	function extractColumn(node: RawProjectNode, statusFieldName: string): string {
273	  const nodes = node.fieldValues?.nodes ?? [];
274	  for (const fv of nodes) {
275	    if (fv.field?.name === statusFieldName && fv.name) {
276	      return fv.name;
277	    }
278	  }
279	  return 'Uncategorized';
280	}
