282	function extractSprint(node: RawProjectNode): { sprint: string; sprintField: string } | undefined {
283	  for (const fv of node.fieldValues?.nodes ?? []) {
284	    if (fv.title !== undefined && fv.field?.name) {
285	      return { sprint: fv.title, sprintField: fv.field.name };
286	    }
287	  }
288	  return undefined;
289	}
