291	function extractLatestReviews(rawReviews: { nodes: Array<{ state: string; author: GHUser }> } | null | undefined): ReviewInfo[] {
292	  const byReviewer = new Map<string, ReviewInfo>();
293	  for (const r of rawReviews?.nodes ?? []) {
294	    if (r?.author) {
295	      byReviewer.set(r.author.login, { state: r.state as ReviewInfo['state'], author: r.author });
296	    }
297	  }
298	  return Array.from(byReviewer.values());
299	}
