566	const LINKED_PRS_QUERY = `
567	query GetLinkedPRs($owner: String!, $repo: String!, $number: Int!) {
568	  repository(owner: $owner, name: $repo) {
569	    issue(number: $number) {
570	      closingPullRequests(first: 10) {
571	        nodes {
572	          number title url state isDraft headRefName
573	          commits(last: 1) { nodes { commit { oid } } }
574	        }
575	      }
576	      timelineItems(first: 25, itemTypes: [CROSS_REFERENCED_EVENT]) {
577	        nodes {
578	          ... on CrossReferencedEvent {
579	            source {
580	              ... on PullRequest {
581	                number title url state isDraft headRefName
582	                commits(last: 1) { nodes { commit { oid } } }
583	              }
584	            }
585	          }
586	        }
587	      }
588	    }
589	  }
590	}
591	`;
