614	async function fetchCheckRunsForCommit(token: string, owner: string, repo: string, sha: string): Promise<CheckRun[]> {
615	  const url = `https://api.github.com/repos/${owner}/${repo}/commits/${sha}/check-runs?per_page=50`;
616	  const resp = await fetch(url, {
617	    headers: {
618	      Authorization: `bearer ${token}`,
619	      Accept: 'application/vnd.github+json',
620	    },
621	  });
622	  if (!resp.ok) return [];
623	  const json = (await resp.json()) as RawCheckRunResponse;
624	  return (json.check_runs ?? []).map((r) => ({
625	    name: r.name,
626	    status: r.status.toUpperCase(),
627	    conclusion: r.conclusion ? r.conclusion.toUpperCase() : null,
628	    detailsUrl: r.details_url ?? r.html_url,
629	  }));
