768	export async function generateStandupMarkdown(viewerLogin: string): Promise<string> {
769	  const token = await getToken();
770	  const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString().split('T')[0];
771	  const today = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
772	
773	  const repoFromUrl = (url: string) => url.replace('https://api.github.com/repos/', '');
774	
775	  async function search(q: string): Promise<RawSearchIssue[]> {
776	    const resp = await fetch(`https://api.github.com/search/issues?q=${encodeURIComponent(q)}&per_page=20`, {
777	      headers: { Authorization: `bearer ${token}`, Accept: 'application/vnd.github+json' },
778	    });
779	    if (!resp.ok) return [];
780	    const json = (await resp.json()) as { items: RawSearchIssue[] };
781	    return json.items ?? [];
782	  }
783	
784	  const [mergedPRs, openPRs, closedIssues] = await Promise.all([
785	    search(`is:pr is:merged author:${viewerLogin} merged:>${yesterday}`),
786	    search(`is:pr is:open author:${viewerLogin}`),
787	    search(`is:issue is:closed assignee:${viewerLogin} closed:>${yesterday}`),
788	  ]);
789	
790	  const lines: string[] = [`## Daily Standup — ${today}`, ''];
791	
792	  if (mergedPRs.length) {
793	    lines.push('### ✅ Merged PRs');
794	    for (const pr of mergedPRs) {
795	      lines.push(`- [#${pr.number} ${pr.title}](${pr.html_url}) *(${repoFromUrl(pr.repository_url)})*`);
796	    }
797	    lines.push('');
798	  }
799	
800	  if (openPRs.length) {
801	    lines.push('### 🔄 Open PRs');
802	    for (const pr of openPRs) {
803	      lines.push(`- [#${pr.number} ${pr.title}](${pr.html_url}) *(${repoFromUrl(pr.repository_url)})*`);
804	    }
805	    lines.push('');
806	  }
807	
808	  if (closedIssues.length) {
809	    lines.push('### 🎯 Issues Closed');
810	    for (const issue of closedIssues) {
811	      lines.push(`- [#${issue.number} ${issue.title}](${issue.html_url}) *(${repoFromUrl(issue.repository_url)})*`);
812	    }
813	    lines.push('');
814	  }
815	
816	  if (!mergedPRs.length && !openPRs.length && !closedIssues.length) {
817	    lines.push('*No activity found in the last 24 hours.*');
818	    lines.push('');
819	  }
820	
821	  lines.push('*Generated by SprintHub*');
822	  return lines.join('\n');
823	}
