913	export async function fetchCodeowners(
914	  owner: string,
915	  repo: string
916	): Promise<Array<{ pattern: string; owners: string[] }>> {
917	  const token = await getToken();
918	
919	  async function tryPath(path: string): Promise<string | null> {
920	    const resp = await fetch(`https://api.github.com/repos/${owner}/${repo}/contents/${path}`, {
921	      headers: { Authorization: `bearer ${token}`, Accept: 'application/vnd.github+json' },
922	    });
923	    if (!resp.ok) return null;
924	    const json = (await resp.json()) as { content?: string; encoding?: string };
925	    if (json.encoding === 'base64' && json.content) {
926	      return atob(json.content.replace(/\n/g, ''));
927	    }
928	    return null;
929	  }
930	
931	  const content =
932	    (await tryPath('.github/CODEOWNERS')) ??
933	    (await tryPath('CODEOWNERS')) ??
934	    (await tryPath('docs/CODEOWNERS'));
935	
936	  if (!content) return [];
937	
938	  const entries: Array<{ pattern: string; owners: string[] }> = [];
939	  for (const line of content.split('\n')) {
940	    const trimmed = line.trim();
941	    if (!trimmed || trimmed.startsWith('#')) continue;
942	    const parts = trimmed.split(/\s+/);
943	    if (parts.length < 2) continue;
944	    entries.push({ pattern: parts[0], owners: parts.slice(1) });
945	  }
946	  return entries;
947	}
