97	          case 'fetchBody':
98	            void this._fetchBody(message.itemId, message.owner, message.repo, message.number, message.isIssue);
99	            break;
100	          // Phase 1: Work-On-This Engine
101	          case 'workOnThis':
102	            void this._workOnThis(message.branchName, message.owner, message.repo);
103	            break;
104	          // Phase 1: File-Level Deep Linking
105	          case 'fetchPRFiles':
106	            void this._fetchPRFiles(message.prKey, message.owner, message.repo, message.prNumber);
107	            break;
108	          case 'openPRFile':
109	            void this._openPRFile(message.owner, message.repo, message.prNumber, message.filename, message.patch);
110	            break;
111	          // Phase 3: Standup Generator
112	          case 'generateStandup':
113	            void this._generateStandup(message.viewerLogin);
114	            break;
115	          // Phase 3: Metadata Sync
116	          case 'updateMetadata':
117	            void this._updateMetadata(message.itemId, message.owner, message.repo, message.issueNumber, message.labels, message.assignees);
118	            break;
119	          case 'fetchRepoLabels':
120	            void this._fetchRepoLabels(message.owner, message.repo);
121	            break;
122	          case 'convertDraftToReady':
123	            void this._convertDraftToReady(message.itemId, message.owner, message.repo, message.prNumber);
124	            break;
125	          case 'mergePR':
126	            void this._mergePR(message.itemId, message.owner, message.repo, message.prNumber, message.mergeMethod);
127	            break;
128	          case 'fetchCodeowners':
129	            void this._fetchCodeowners(message.owner, message.repo);
130	            break;
131	        }
132	      },
133	      null,
134	      this._disposables
135	    );
136	
137	    vscode.workspace.onDidChangeConfiguration(
138	      (e) => {
139	        if (e.affectsConfiguration('sprinthub')) {
140	          this._sendConfig();
141	          this._loadData();
142	          this._scheduleRefresh();
143	        }
144	      },
145	      null,
146	      this._disposables
147	    );
148	
149	    this._loadData();
150	    this._sendConfig();
151	    this._scheduleRefresh();
152	  }
