256	  private async _workOnThis(branchName: string, _owner: string, _repo: string) {
257	    const cwd = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath;
258	    if (!cwd) {
259	      vscode.window.showErrorMessage('SprintHub: No workspace folder open to checkout branch.');
260	      return;
261	    }
262	
263	    let branchExists = false;
264	    try {
265	      await exec(`git rev-parse --verify "${branchName}"`, { cwd });
266	      branchExists = true;
267	    } catch {
268	      branchExists = false;
269	    }
270	
271	    let terminal = vscode.window.terminals.find((t) => t.name === 'SprintHub');
272	    if (!terminal) {
273	      terminal = vscode.window.createTerminal('SprintHub');
274	    }
275	    terminal.show(true);
276	
277	    if (branchExists) {
278	      terminal.sendText(`git checkout ${branchName}`);
279	    } else {
280	      terminal.sendText(`git fetch origin ${branchName} 2>/dev/null; git checkout -b ${branchName} origin/${branchName} 2>/dev/null || git checkout ${branchName}`);
281	    }
282	
283	    // Focus the most recently modified file in the workspace
284	    setTimeout(() => void this._focusMostRecentFile(cwd), 2000);
285	  }
