287	  private async _focusMostRecentFile(cwd: string) {
288	    try {
289	      const { stdout } = await exec('git diff --name-only HEAD', { cwd });
290	      const files = stdout.trim().split('\n').filter(Boolean);
291	      if (!files.length) return;
292	      const found = await vscode.workspace.findFiles(files[0], '**/node_modules/**', 1);
293	      if (found.length) {
294	        const doc = await vscode.workspace.openTextDocument(found[0]);
295	        await vscode.window.showTextDocument(doc, { preserveFocus: false });
296	      }
297	    } catch {
298	      // silently skip if git diff fails (detached HEAD, etc.)
299	    }
300	  }
