313	  private async _openPRFile(owner: string, repo: string, _prNumber: number, filename: string, patch?: string) {
314	    const cwd = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath;
315	    if (!cwd) {
316	      vscode.window.showWarningMessage('SprintHub: No workspace folder open.');
317	      return;
318	    }
319	
320	    const found = await vscode.workspace.findFiles(filename, '**/node_modules/**', 1);
321	    if (!found.length) {
322	      vscode.window.showWarningMessage(`SprintHub: File not found locally: ${filename}`);
323	      return;
