338	  private async _checkConflicts(data: RunwayData) {
339	    const cwd = vscode.workspace.workspaceFolders?.[0]?.uri.fsPath;
340	    if (!cwd) return;
341	
342	    let localDirty: Set<string>;
343	    try {
344	      const { stdout } = await exec('git diff --name-only HEAD', { cwd });
345	      localDirty = new Set(stdout.trim().split('\n').filter(Boolean));
346	    } catch {
347	      return;
348	    }
349	
350	    if (!localDirty.size) {
351	      this._post({ type: 'conflictThreats', threats: [] });
352	      return;
353	    }
354	
355	    // Collect open PRs from board + linked PRs
356	    const openPRs: Array<{ owner: string; repo: string; number: number; title: string; author: string; url: string }> = [];
357	    const allBoardItems: BoardItem[] = [...Object.values(data.groups).flat(), ...(data.linkedIssuePRs ?? [])];
358	    for (const item of allBoardItems) {
359	      if (item.type === 'PULL_REQUEST' && item.state === 'OPEN' && item.repositoryOwner && item.repository) {
360	        openPRs.push({
361	          owner: item.repositoryOwner,
362	          repo: item.repository,
363	          number: item.number,
364	          title: item.title,
365	          author: item.author.login,
366	          url: item.url,
367	        });
368	      }
369	    }
370	
371	    if (!openPRs.length) {
372	      this._post({ type: 'conflictThreats', threats: [] });
373	      return;
374	    }
375	
376	    try {
377	      const prFilesMap = await fetchAllOpenPRFiles(openPRs.map((p) => ({ owner: p.owner, repo: p.repo, number: p.number })));
378	      const threats: ConflictThreat[] = [];
379	
380	      for (const pr of openPRs) {
381	        const key = `${pr.owner}/${pr.repo}#${pr.number}`;
382	        const files = prFilesMap.get(key) ?? [];
383	        for (const file of files) {
384	          if (localDirty.has(file.filename)) {
385	            threats.push({
386	              filename: file.filename,
387	              prNumber: pr.number,
388	              prTitle: pr.title,
389	              prAuthor: pr.author,
390	              prUrl: pr.url,
391	            });
392	          }
393	        }
394	      }
395	
396	      this._post({ type: 'conflictThreats', threats });
397	    } catch {
398	      // conflict check is best-effort
399	    }
400	  }
