404	  private _updateStatusBar(data: RunwayData) {
405	    const allItems: BoardItem[] = [...Object.values(data.groups).flat(), ...(data.linkedIssuePRs ?? [])];
406	    const openPRs = allItems.filter((i) => i.type === 'PULL_REQUEST' && i.state === 'OPEN');
407	
408	    const ciFailures = openPRs.filter((i) => i.ciState === 'FAILURE' || i.ciState === 'ERROR');
409	    const changesRequested = openPRs.filter((i) =>
410	      i.reviews?.some((r) => r.state === 'CHANGES_REQUESTED')
411	    );
412	
413	    const total = ciFailures.length + changesRequested.length;
414	
415	    if (total === 0) {
416	      this._statusBarItem.text = '$(check) SprintHub';
417	      this._statusBarItem.backgroundColor = undefined;
418	    } else {
419	      const parts: string[] = [];
420	      if (ciFailures.length) parts.push(`${ciFailures.length} CI fail${ciFailures.length > 1 ? 's' : ''}`);
421	      if (changesRequested.length) parts.push(`${changesRequested.length} changes req`);
422	      this._statusBarItem.text = `$(warning) ${parts.join(' · ')}`;
423	      this._statusBarItem.backgroundColor = new vscode.ThemeColor('statusBarItem.warningBackground');
424	    }
425	
426	    this._statusBarItem.show();
427	
428	    // Store for use in showBlockers quick-pick
429	    (this as unknown as Record<string, unknown>)._blockerPRs = { ciFailures, changesRequested };
430	  }
