432	  public showBlockersQuickPick() {
433	    const stored = (this as unknown as Record<string, unknown>)._blockerPRs as
434	      | { ciFailures: BoardItem[]; changesRequested: BoardItem[] }
435	      | undefined;
436	    if (!stored) {
437	      vscode.window.showInformationMessage('SprintHub: No blocker data loaded yet.');
438	      return;
439	    }
440	
441	    const { ciFailures, changesRequested } = stored;
442	    const items: vscode.QuickPickItem[] = [];
443	
444	    if (ciFailures.length) {
445	      items.push({ label: '$(error) CI Failing', kind: vscode.QuickPickItemKind.Separator });
446	      for (const pr of ciFailures) {
447	        items.push({ label: `#${pr.number} ${pr.title}`, description: `${pr.repositoryOwner}/${pr.repository}`, detail: pr.url });
448	      }
449	    }
450	
451	    if (changesRequested.length) {
452	      items.push({ label: '$(git-pull-request) Changes Requested', kind: vscode.QuickPickItemKind.Separator });
453	      for (const pr of changesRequested) {
454	        items.push({ label: `#${pr.number} ${pr.title}`, description: `${pr.repositoryOwner}/${pr.repository}`, detail: pr.url });
455	      }
456	    }
457	
458	    if (!items.length) {
459	      vscode.window.showInformationMessage('SprintHub: All PRs are healthy!');
460	      return;
461	    }
462	
463	    void vscode.window.showQuickPick(items, { title: 'SprintHub Blockers', placeHolder: 'Select a PR to open on GitHub' }).then((selected) => {
464	      if (selected?.detail) {
465	        void vscode.env.openExternal(vscode.Uri.parse(selected.detail));
466	      }
467	    });
468	  }
