12	// ─── Group logic ────────────────────────────────────────────────────────────
13	
14	type LaunchpadGroup =
15	  | 'Ready to Merge'
16	  | 'Changes Requested'
17	  | 'CI Failing'
18	  | 'Ready for Review'
19	  | 'Needs Review'
20	  | 'In Progress'
21	  | 'Draft';
22	
23	const GROUP_ORDER: LaunchpadGroup[] = [
24	  'Ready to Merge',
25	  'Changes Requested',
26	  'CI Failing',
27	  'Ready for Review',
28	  'Needs Review',
29	  'In Progress',
30	  'Draft',
31	];
32	
33	const GROUP_META: Record<LaunchpadGroup, { color: string; icon: string; desc: string }> = {
34	  'Ready to Merge':    { color: '#a6e3a1', icon: '🚀', desc: 'Approved and all checks passed' },
35	  'Changes Requested': { color: '#f38ba8', icon: '✗',  desc: 'Review requested changes' },
36	  'CI Failing':        { color: '#f38ba8', icon: '✕',  desc: 'Checks are failing' },
37	  'Ready for Review':  { color: '#f9e2af', icon: '👁',  desc: 'In the Ready for Review column — awaiting review' },
38	  'Needs Review':      { color: '#cba6f7', icon: '❓',  desc: 'No reviewer assigned yet' },
39	  'In Progress':       { color: '#89b4fa', icon: '◑',  desc: 'Work in progress' },
40	  'Draft':             { color: '#585b70', icon: '✎',  desc: 'Draft pull requests' },
41	};
42	
43	function getPRGroup(item: BoardItem): LaunchpadGroup {
44	  if (item.isDraft) return 'Draft';
45	
46	  const hasChangesRequested = item.reviews?.some((r) => r.state === 'CHANGES_REQUESTED');
47	  if (hasChangesRequested) return 'Changes Requested';
48	
49	  if (item.ciState === 'FAILURE' || item.ciState === 'ERROR') return 'CI Failing';
50	
51	  const isApproved = item.reviews?.some((r) => r.state === 'APPROVED');
52	  const ciOk = !item.ciState || item.ciState === 'SUCCESS' || item.ciState === 'none' || item.ciState === 'EXPECTED';
53	  if (isApproved && ciOk) return 'Ready to Merge';
54	
55	  // Board column "Ready for review" (case-insensitive) takes priority over generic grouping
56	  if (item.column?.toLowerCase() === 'ready for review') return 'Ready for Review';
57	
58	  // No reviewer assigned at all → clearly needs someone to pick it up
59	  const hasAnyReview = item.reviews?.some(
60	    (r) => r.state === 'APPROVED' || r.state === 'COMMENTED' || r.state === 'CHANGES_REQUESTED'
61	  );
62	  if (!hasAnyReview && !item.reviewRequests?.length) return 'Needs Review';
63	
64	  return 'In Progress';
65	}
