69	function timeAgo(iso: string): string {
70	  const diff = Date.now() - new Date(iso).getTime();
71	  const mins = Math.floor(diff / 60000);
72	  if (mins < 60) return `${Math.max(1, mins)}m`;
73	  const hours = Math.floor(mins / 60);
74	  if (hours < 24) return `${hours}h`;
75	  const days = Math.floor(hours / 24);
76	  if (days < 30) return `${days}d`;
