6	function matchesCodeownersPattern(filename: string, pattern: string): boolean {
7	  const p = pattern.startsWith('/') ? pattern.slice(1) : pattern;
8	  if (p.endsWith('/')) return filename.startsWith(p);
9	  if (p.startsWith('*.')) return filename.endsWith(p.slice(1));
10	  if (p.includes('*')) {
11	    const re = new RegExp('^' + p.replace(/\./g, '\\.').replace(/\*/g, '[^/]*') + '$');
12	    return re.test(filename) || re.test(filename.split('/').pop() ?? '');
13	  }
14	  return filename === p || filename.startsWith(p + '/');
15	}
16	
17	export function resolveCodeowners(
18	  filename: string,
19	  entries: Array<{ pattern: string; owners: string[] }>
20	): string[] {
21	  let matched: string[] = [];
22	  for (const entry of entries) {
23	    if (matchesCodeownersPattern(filename, entry.pattern)) {
24	      matched = entry.owners;
25	    }
26	  }
27	  return matched;
28	}
