37	function computeQualityFlags(item: BoardItem, files: PRFile[] | null): QualityFlag[] {
38	  const flags: QualityFlag[] = [];
39	  const daysOpen = (Date.now() - new Date(item.createdAt).getTime()) / 86_400_000;
40	  const totalLines = (item.additions ?? 0) + (item.deletions ?? 0);
41	
42	  if (daysOpen > 7) flags.push({ label: `Stale · ${Math.floor(daysOpen)}d open`, color: '#f9e2af' });
43	  if (totalLines > 500) flags.push({ label: `Large · ${totalLines} lines`, color: '#f38ba8' });
44	  if (!item.body?.trim()) flags.push({ label: 'No description', color: '#fab387' });
45	  if (!item.reviewRequests?.length && !item.reviews?.length) {
46	    flags.push({ label: 'No reviewers', color: '#fab387' });
47	  }
48	  if (files && files.length > 0 && !files.some((f) => /test|spec/i.test(f.filename))) {
49	    flags.push({ label: 'No tests changed', color: '#a6adc8' });
50	  }
51	  return flags;
52	}
