56	function timeAgo(iso: string): string {
57	  const diff = Date.now() - new Date(iso).getTime();
58	  const mins = Math.floor(diff / 60000);
59	  if (mins < 2) return 'just now';
60	  if (mins < 60) return `${mins}m ago`;
61	  const hours = Math.floor(mins / 60);
62	  if (hours < 24) return `${hours}h ago`;
63	  const days = Math.floor(hours / 24);
64	  if (days < 30) return `${days}d ago`;
65	  return new Date(iso).toLocaleDateString();
66	}
