68	function ciColor(conclusion: string | null, status: string): string {
69	  if (status === 'IN_PROGRESS' || status === 'QUEUED') return '#f9e2af';
70	  if (conclusion === 'SUCCESS') return '#a6e3a1';
71	  if (conclusion === 'FAILURE' || conclusion === 'TIMED_OUT') return '#f38ba8';
72	  if (conclusion === 'CANCELLED') return '#6c7086';
73	  return '#585b70';
74	}
