76	function ciLabel(conclusion: string | null, status: string): string {
77	  if (status === 'IN_PROGRESS') return 'running';
78	  if (['QUEUED', 'REQUESTED', 'WAITING', 'PENDING'].includes(status)) return 'queued';
79	  if (conclusion === 'SUCCESS') return 'pass';
80	  if (conclusion === 'FAILURE') return 'fail';
81	  if (conclusion === 'TIMED_OUT') return 'timeout';
82	  if (conclusion === 'CANCELLED') return 'cancelled';
83	  if (conclusion === 'SKIPPED') return 'skipped';
84	  if (conclusion === 'NEUTRAL') return 'neutral';
85	  return status.toLowerCase();
86	}
