285	function MergeButton({ item, onMerge }: { item: BoardItem; onMerge: (method: 'merge' | 'squash' | 'rebase') => void }) {
286	  const [open, setOpen] = useState(false);
287	  const ref = useRef<HTMLDivElement>(null);
288	
289	  useEffect(() => {
290	    const close = (e: MouseEvent) => { if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false); };
291	    document.addEventListener('mousedown', close);
292	    return () => document.removeEventListener('mousedown', close);
293	  }, []);
294	
295	  const isReady =
296	    item.ciState === 'SUCCESS' &&
297	    item.reviews?.some((r) => r.state === 'APPROVED') &&
298	    !item.reviews?.some((r) => r.state === 'CHANGES_REQUESTED');
299	
300	  if (!isReady) return null;
301	
302	  const options: Array<{ method: 'merge' | 'squash' | 'rebase'; label: string; desc: string }> = [
303	    { method: 'squash', label: 'Squash and merge', desc: 'Combine all commits into one' },
304	    { method: 'merge', label: 'Create a merge commit', desc: 'Preserve all commits with a merge commit' },
305	    { method: 'rebase', label: 'Rebase and merge', desc: 'Rebase commits onto the base branch' },
306	  ];
307	
308	  return (
309	    <div ref={ref} style={{ position: 'relative' }}>
310	      <button className="detail-merge-btn" onClick={() => setOpen((v) => !v)}>
311	        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
312	          <circle cx="18" cy="18" r="3"/><circle cx="6" cy="6" r="3"/>
313	          <path d="M6 21V9a9 9 0 0 0 9 9"/>
314	        </svg>
315	        Merge
316	        <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"
317	          style={{ transform: open ? 'rotate(180deg)' : 'none', transition: 'transform 0.15s' }}>
318	          <polyline points="6 9 12 15 18 9"/>
319	        </svg>
320	      </button>
321	      {open && (
322	        <div className="merge-dropdown">
323	          {options.map((opt) => (
324	            <button key={opt.method} className="merge-dropdown-item"
325	              onClick={() => { setOpen(false); onMerge(opt.method); }}>
326	              <span className="merge-dropdown-label">{opt.label}</span>
327	              <span className="merge-dropdown-desc">{opt.desc}</span>
328	            </button>
329	          ))}
330	        </div>
331	      )}
332	    </div>
333	  );
334	}
