338	function MetadataEditor({
339	  item, repoLabels, onUpdateMetadata, onFetchRepoLabels,
340	}: {
341	  item: BoardItem;
342	  repoLabels: GHLabel[];
343	  onUpdateMetadata: (itemId: string, owner: string, repo: string, issueNumber: number, labels?: string[]) => void;
344	  onFetchRepoLabels: (owner: string, repo: string) => void;
345	}) {
346	  const [localLabels, setLocalLabels] = useState<GHLabel[]>(item.labels);
347	  const [labelDropOpen, setLabelDropOpen] = useState(false);
348	
349	  useEffect(() => { setLocalLabels(item.labels); }, [item.id, item.labels]);
350	
351	  const removeLabel = (name: string) => {
352	    const next = localLabels.filter((l) => l.name !== name);
353	    setLocalLabels(next);
354	    onUpdateMetadata(item.id, item.repositoryOwner, item.repository, item.number, next.map((l) => l.name));
355	  };
356	
357	  const addLabel = (label: GHLabel) => {
358	    if (localLabels.some((l) => l.name === label.name)) return;
359	    const next = [...localLabels, label];
360	    setLocalLabels(next);
361	    setLabelDropOpen(false);
362	    onUpdateMetadata(item.id, item.repositoryOwner, item.repository, item.number, next.map((l) => l.name));
363	  };
364	
365	  const toggleDrop = () => {
366	    if (!labelDropOpen && !repoLabels.length) onFetchRepoLabels(item.repositoryOwner, item.repository);
367	    setLabelDropOpen((v) => !v);
368	  };
369	
370	  const available = repoLabels.filter((l) => !localLabels.some((ll) => ll.name === l.name));
371	
372	  return (
373	    <div className="metadata-editor">
374	      <div className="metadata-editor-row">
375	        <span className="metadata-editor-label">Labels</span>
376	        <div className="metadata-editor-tags">
377	          {localLabels.map((label) => {
378	            const bg = `#${label.color}`;
379	            return (
380	              <span key={label.name} className="label metadata-tag" style={{ background: bg + '33', color: bg, border: `1px solid ${bg}55` }}>
381	                {label.name}
382	                <button className="metadata-tag-remove" onClick={() => removeLabel(label.name)}>×</button>
383	              </span>
384	            );
385	          })}
386	          <div style={{ position: 'relative' }}>
387	            <button className="metadata-add-btn" onClick={toggleDrop}>+</button>
388	            {labelDropOpen && (
389	              <div className="metadata-dropdown">
390	                {!repoLabels.length && <div style={{ padding: '6px 10px', fontSize: 11, color: '#45475a' }}>Loading…</div>}
391	                {!available.length && repoLabels.length > 0 && <div style={{ padding: '6px 10px', fontSize: 11, color: '#45475a' }}>All labels applied</div>}
392	                {available.map((label) => {
393	                  const bg = `#${label.color}`;
394	                  return (
395	                    <button key={label.name} className="metadata-dropdown-item" onClick={() => addLabel(label)}>
396	                      <span style={{ width: 10, height: 10, borderRadius: '50%', background: bg, display: 'inline-block', flexShrink: 0 }} />
397	                      {label.name}
398	                    </button>
399	                  );
400	                })}
401	              </div>
402	            )}
403	          </div>
404	        </div>
405	      </div>
406	    </div>
407	  );
408	}
