139	export function ItemCard({ item, onSelect, onOpenUrl }: Props) {
140	  const isPR = item.type === 'PULL_REQUEST';
141	
142	  return (
143	    <div className="item-card" onClick={() => onSelect(item)}>
144	      {/* Top row: icon + title + number + github link */}
145	      <div className="item-top">
146	        <span className="item-type">
147	          {isPR ? (
148	            <PRIcon state={item.state} isDraft={item.isDraft} />
149	          ) : (
150	            <IssueIcon state={item.state} />
151	          )}
152	        </span>
153	
154	        <div className="item-body">
155	          <div className="item-title-row">
156	            <span className="item-title">{item.title}</span>
157	            <span className="item-num">#{item.number}</span>
158	            <button
159	              className="card-gh-link"
160	              onClick={(e) => { e.stopPropagation(); onOpenUrl(item.url); }}
161	              title="View on GitHub"
162	            >
163	              <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
164	                <path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/>
165	                <polyline points="15 3 21 3 21 9"/>
166	                <line x1="10" y1="14" x2="21" y2="3"/>
167	              </svg>
168	            </button>
169	          </div>
170	
171	          {/* Bottom row: labels + meta */}
172	          <div className="item-bottom">
173	            {/* Draft badge */}
174	            {isPR && item.isDraft && <span className="draft-badge">Draft</span>}
175	
176	            {/* Labels */}
177	            {item.labels.map((label) => {
178	              const bg = `#${label.color}`;
179	              const r = parseInt(label.color.substring(0, 2), 16);
180	              const g = parseInt(label.color.substring(2, 4), 16);
181	              const b = parseInt(label.color.substring(4, 6), 16);
182	              const lum = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
183	              // lum is calculated but used only for potential future text color logic
184	              void lum;
185	              return (
186	                <span
187	                  key={label.name}
188	                  className="label"
189	                  style={{ background: bg + '33', color: bg, border: `1px solid ${bg}55` }}
190	                >
191	                  {label.name}
192	                </span>
193	              );
194	            })}
195	
196	            {/* Meta: right side */}
197	            <span className="item-meta">
198	              {/* Diff stats (PR only) */}
199	              {isPR && item.additions !== undefined && (
200	                <span className="diff-stats">
201	                  <span className="diff-add">+{item.additions}</span>
202	                  <span className="diff-del">-{item.deletions ?? 0}</span>
203	                </span>
204	              )}
205	
206	              {/* CI status */}
207	              {isPR && <CIIcon state={item.ciState} />}
208	
209	              {/* Review status */}
210	              {isPR && (
211	                <ReviewIcons reviews={item.reviews} requests={item.reviewRequests} />
212	              )}
213	
214	              {/* Branch */}
215	              {isPR && item.headRefName && (
216	                <span className="branch-tag" title={item.headRefName}>
217	                  <BranchIcon />
218	                  {item.headRefName}
219	                </span>
220	              )}
221	
222	              {/* Repo */}
223	              <span className="repo-tag">
224	                <RepoIcon />
225	                {item.repository}
226	              </span>
227	
228	              {/* Assignees */}
229	              {item.assignees.length > 0 && (
230	                <span className="avatar-group">
231	                  {item.assignees.slice(0, 3).map((a) => (
232	                    <Avatar key={a.login} user={a} />
233	                  ))}
234	                  {item.assignees.length > 3 && (
235	                    <span className="avatar" title={`+${item.assignees.length - 3} more`}>
236	                      <span className="avatar-placeholder">+{item.assignees.length - 3}</span>
237	                    </span>
238	                  )}
239	                </span>
240	              )}
241	
242	              {/* Author */}
243	              <Avatar user={item.author} />
244	            </span>
245	          </div>
246	        </div>
247	      </div>
248	    </div>
249	  );
250	}
